ko:
# /etc/apache2/svn-authz (예시) — 쓰기는 관리자만, 다른 인증 사용자는 읽기만
[groups]
admins = &lt;admin-user&gt;

[/]
@admins = rw
* = r

en:
# /etc/apache2/svn-authz (example) — write for admins only, other authenticated users read-only
[groups]
admins = &lt;admin-user&gt;

[/]
@admins = rw
* = r

ja:
# /etc/apache2/svn-authz(例)— 書き込みは管理者のみ、他の認証ユーザーは読み取りのみ
[groups]
admins = &lt;admin-user&gt;

[/]
@admins = rw
* = r

zh:
# /etc/apache2/svn-authz(示例)— 仅管理员可写,其他已认证用户只读
[groups]
admins = &lt;admin-user&gt;

[/]
@admins = rw
* = r

ko:
-- SQL Editor에서 1회 실행 (스키마 주인은 postgres: PG16의 SET ROLE 규칙 때문)
create role popspot_api with login password '…';
create schema if not exists popspot;
grant usage, create on schema popspot to popspot_api;
alter role popspot_api set search_path = popspot;

-- 관리자 지정: 테이블 주인이 popspot_api라 잠깐 그 역할로 전환
grant popspot_api to postgres with inherit false, set true;   -- 최초 1회
set role popspot_api;
insert into popspot.user_roles (user_id, role)
select id, 'ADMIN' from popspot.app_users where email = '…' on conflict do nothing;
reset role;

en:
-- Run once in SQL Editor (schema owner is postgres because of PG16's SET ROLE rules)
create role popspot_api with login password '…';
create schema if not exists popspot;
grant usage, create on schema popspot to popspot_api;
alter role popspot_api set search_path = popspot;

-- Assign admin: tables are owned by popspot_api, so briefly switch to that role
grant popspot_api to postgres with inherit false, set true;   -- first time only
set role popspot_api;
insert into popspot.user_roles (user_id, role)
select id, 'ADMIN' from popspot.app_users where email = '…' on conflict do nothing;
reset role;

ja:
-- SQL Editor で 1 回実行 (スキーマの所有者は postgres: PG16 の SET ROLE ルールのため)
create role popspot_api with login password '…';
create schema if not exists popspot;
grant usage, create on schema popspot to popspot_api;
alter role popspot_api set search_path = popspot;

-- 管理者の指定: テーブルの所有者が popspot_api なので一時的にそのロールへ切り替え
grant popspot_api to postgres with inherit false, set true;   -- 初回のみ
set role popspot_api;
insert into popspot.user_roles (user_id, role)
select id, 'ADMIN' from popspot.app_users where email = '…' on conflict do nothing;
reset role;

zh:
-- 在 SQL Editor 中执行一次 (schema 所有者为 postgres：因 PG16 的 SET ROLE 规则)
create role popspot_api with login password '…';
create schema if not exists popspot;
grant usage, create on schema popspot to popspot_api;
alter role popspot_api set search_path = popspot;

-- 指定管理员：表的所有者是 popspot_api，因此临时切换到该角色
grant popspot_api to postgres with inherit false, set true;   -- 仅首次
set role popspot_api;
insert into popspot.user_roles (user_id, role)
select id, 'ADMIN' from popspot.app_users where email = '…' on conflict do nothing;
reset role;

ko:
# Provider 조건: 이 저장소 main의 deploy.yml / rollback.yml만 (교차 리뷰 지적 반영)
